// Runtime for code generated by Rabbinatix from Logic Blueprints. Do not edit: it is regenerated on export.
// Every helper mirrors the simulator, so generated handlers behave exactly like their blueprints.
// Values are JSON values: *Object, []any, string, float64, bool and nil.
package main

import (
	"crypto/hmac"
	"crypto/md5"
	crand "crypto/rand"
	"crypto/sha1"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"hash"
	"math"
	"math/big"
	mrand "math/rand"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
	"unicode/utf16"
	"unicode/utf8"
)

// FddError is an error with a code, like the simulator's errors (Throw nodes, DIVIDE_BY_ZERO, INVALID_JSON...).
type FddError struct {
	Code    string
	Message string
}

func (e *FddError) Error() string { return e.Message }

// NewFddError makes an FddError; a boundary returns one to fail with a code.
func NewFddError(code, message string) *FddError { return &FddError{Code: code, Message: message} }

// Object is a JSON object that keeps its keys in order.
type Object struct {
	keys []string
	vals map[string]any
}

// NewObject makes an empty Object.
func NewObject() *Object { return &Object{vals: map[string]any{}} }

// Get reads a field; ok is false when the object has no such field.
func (o *Object) Get(key string) (value any, ok bool) {
	if o == nil {
		return nil, false
	}
	value, ok = o.vals[key]
	return value, ok
}

// Set writes a field (a new field goes last).
func (o *Object) Set(key string, value any) {
	if _, ok := o.vals[key]; !ok {
		o.keys = append(o.keys, key)
	}
	o.vals[key] = value
}

// Delete removes a field.
func (o *Object) Delete(key string) {
	if _, ok := o.vals[key]; !ok {
		return
	}
	delete(o.vals, key)
	for i, k := range o.keys {
		if k == key {
			o.keys = append(o.keys[:i:i], o.keys[i+1:]...)
			break
		}
	}
}

// Keys lists the field names in JavaScript's order: integer-like keys ascending, then the rest as inserted.
func (o *Object) Keys() []string {
	if o == nil {
		return nil
	}
	var index, rest []string
	for _, k := range o.keys {
		if isIndexKey(k) {
			index = append(index, k)
		} else {
			rest = append(rest, k)
		}
	}
	sort.SliceStable(index, func(i, j int) bool {
		a, _ := strconv.ParseFloat(index[i], 64)
		b, _ := strconv.ParseFloat(index[j], 64)
		return a < b
	})
	return append(index, rest...)
}

// Len is the number of fields.
func (o *Object) Len() int {
	if o == nil {
		return 0
	}
	return len(o.keys)
}

// MarshalJSON writes the object as JSON, in its key order.
func (o *Object) MarshalJSON() ([]byte, error) { return []byte(fdd.json(o)), nil }

// ToValue converts your own values (structs with json tags, maps, slices, numbers) to the JSON values the handlers take.
func ToValue(v any) (any, error) {
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return ParseJSON(string(b))
}

// FromValue converts JSON values to your own type, as encoding/json does: FromValue(result, &resp).
func FromValue(v any, out any) error { return json.Unmarshal([]byte(fdd.json(v)), out) }

// ParseJSON reads JSON text as JSON values.
func ParseJSON(text string) (any, error) {
	r := &jsonReader{s: text}
	r.ws()
	v, err := r.value()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.i != len(r.s) {
		return nil, r.bad()
	}
	return v, nil
}

// StringifyJSON writes JSON values as JSON text (JSON.stringify).
func StringifyJSON(v any) string { return fdd.json(v) }

type jsonReader struct {
	s string
	i int
}

func (r *jsonReader) bad() error { return fmt.Errorf("not valid JSON at %d", r.i) }

func (r *jsonReader) ws() {
	for r.i < len(r.s) {
		c := r.s[r.i]
		if c != ' ' && c != '\t' && c != '\n' && c != '\r' {
			break
		}
		r.i++
	}
}

func (r *jsonReader) value() (any, error) {
	if r.i >= len(r.s) {
		return nil, r.bad()
	}
	switch c := r.s[r.i]; {
	case c == '{':
		return r.object()
	case c == '[':
		return r.array()
	case c == '"':
		return r.str()
	case strings.HasPrefix(r.s[r.i:], "true"):
		r.i += 4
		return true, nil
	case strings.HasPrefix(r.s[r.i:], "false"):
		r.i += 5
		return false, nil
	case strings.HasPrefix(r.s[r.i:], "null"):
		r.i += 4
		return nil, nil
	}
	return r.number()
}

func (r *jsonReader) object() (any, error) {
	o := NewObject()
	r.i++
	r.ws()
	if r.i < len(r.s) && r.s[r.i] == '}' {
		r.i++
		return o, nil
	}
	for {
		r.ws()
		if r.i >= len(r.s) || r.s[r.i] != '"' {
			return nil, r.bad()
		}
		k, err := r.str()
		if err != nil {
			return nil, err
		}
		r.ws()
		if r.i >= len(r.s) || r.s[r.i] != ':' {
			return nil, r.bad()
		}
		r.i++
		r.ws()
		v, err := r.value()
		if err != nil {
			return nil, err
		}
		o.Set(k, v)
		r.ws()
		if r.i >= len(r.s) {
			return nil, r.bad()
		}
		c := r.s[r.i]
		r.i++
		if c == '}' {
			return o, nil
		}
		if c != ',' {
			return nil, r.bad()
		}
	}
}

func (r *jsonReader) array() (any, error) {
	l := []any{}
	r.i++
	r.ws()
	if r.i < len(r.s) && r.s[r.i] == ']' {
		r.i++
		return l, nil
	}
	for {
		r.ws()
		v, err := r.value()
		if err != nil {
			return nil, err
		}
		l = append(l, v)
		r.ws()
		if r.i >= len(r.s) {
			return nil, r.bad()
		}
		c := r.s[r.i]
		r.i++
		if c == ']' {
			return l, nil
		}
		if c != ',' {
			return nil, r.bad()
		}
	}
}

func (r *jsonReader) str() (string, error) {
	r.i++
	var units []uint16
	for {
		if r.i >= len(r.s) {
			return "", r.bad()
		}
		c := r.s[r.i]
		if c == '"' {
			r.i++
			return string(utf16.Decode(units)), nil
		}
		if c < 0x20 {
			return "", r.bad()
		}
		if c != '\\' {
			ch, size := utf8.DecodeRuneInString(r.s[r.i:])
			units = utf16.AppendRune(units, ch)
			r.i += size
			continue
		}
		r.i++
		if r.i >= len(r.s) {
			return "", r.bad()
		}
		e := r.s[r.i]
		r.i++
		switch e {
		case '"', '\\', '/':
			units = append(units, uint16(e))
		case 'b':
			units = append(units, '\b')
		case 'f':
			units = append(units, '\f')
		case 'n':
			units = append(units, '\n')
		case 'r':
			units = append(units, '\r')
		case 't':
			units = append(units, '\t')
		case 'u':
			if r.i+4 > len(r.s) {
				return "", r.bad()
			}
			n, err := strconv.ParseUint(r.s[r.i:r.i+4], 16, 16)
			if err != nil {
				return "", r.bad()
			}
			units = append(units, uint16(n))
			r.i += 4
		default:
			return "", r.bad()
		}
	}
}

func (r *jsonReader) number() (any, error) {
	start := r.i
	digits := func() bool {
		s := r.i
		for r.i < len(r.s) && r.s[r.i] >= '0' && r.s[r.i] <= '9' {
			r.i++
		}
		return r.i > s
	}
	if r.i < len(r.s) && r.s[r.i] == '-' {
		r.i++
	}
	if r.i < len(r.s) && r.s[r.i] == '0' {
		r.i++
	} else if !digits() {
		return nil, r.bad()
	}
	if r.i < len(r.s) && r.s[r.i] == '.' {
		r.i++
		if !digits() {
			return nil, r.bad()
		}
	}
	if r.i < len(r.s) && (r.s[r.i] == 'e' || r.s[r.i] == 'E') {
		r.i++
		if r.i < len(r.s) && (r.s[r.i] == '+' || r.s[r.i] == '-') {
			r.i++
		}
		if !digits() {
			return nil, r.bad()
		}
	}
	f, err := strconv.ParseFloat(r.s[start:r.i], 64)
	if err != nil && !errors.Is(err, strconv.ErrRange) {
		return nil, r.bad()
	}
	return f, nil
}

// fddRuntime holds the helpers the generated handlers call: fdd.getPath(...), fdd.truthy(...)...
type fddRuntime struct{}

var fdd fddRuntime

// a path that isn't there (JavaScript's undefined): left out of objects, like JSON.stringify does
type fddMissing struct{}

var missing any = &fddMissing{}

// fddAborter is a panic the generated code must not catch (verification stops)
type fddAborter interface{ FddAbort() }

// ---------- control flow ----------

// recoverInto turns a panic into the handler's error (defer it).
func (fddRuntime) recoverInto(err *error) {
	if r := recover(); r != nil {
		if _, ok := r.(fddAborter); ok {
			panic(r)
		}
		*err = fdd.asError(r)
	}
}

func (fddRuntime) asError(r any) error {
	switch e := r.(type) {
	case *FddError:
		return e
	case error:
		return e
	}
	return errors.New(fdd.jsString(r))
}

// try runs body; when it panics, catch runs with the panic. Each returns how control leaves: 0 on, 1 return, 2 break.
func (fddRuntime) try(body func() int, catch func(e any) int) (flow int) {
	var caught any
	failed := false
	func() {
		defer func() {
			if r := recover(); r != nil {
				if _, ok := r.(fddAborter); ok {
					panic(r)
				}
				caught, failed = r, true
			}
		}()
		flow = body()
	}()
	if failed {
		return catch(caught)
	}
	return flow
}

// must is the value of a call that can fail: the error is raised.
func (fddRuntime) must(v any, err error) any {
	if err != nil {
		panic(err)
	}
	return v
}

func (fddRuntime) raise(code, message any) any {
	panic(&FddError{Code: fdd.asString(code), Message: fdd.asString(message)})
}

// ifElse is cond ? a() : b().
func (fddRuntime) ifElse(cond bool, a, b func() any) any {
	if cond {
		return a()
	}
	return b()
}

// pick is cond ? a : b, both already evaluated.
func (fddRuntime) pick(cond bool, a, b any) any {
	if cond {
		return a
	}
	return b
}

// ---------- the value model the generated code uses ----------

// get is o.name, null-safe: nil when o is nil or has no such field.
func (fddRuntime) get(o any, name string) any { return fdd.key(o, name) }

// item is o[k], null-safe.
func (fddRuntime) item(o any, k any) any { return fdd.key(o, k) }

// obj makes an object from key, value, key, value...
func (fddRuntime) obj(fields ...any) any {
	d := NewObject()
	for i := 0; i+1 < len(fields); i += 2 {
		d.Set(fields[i].(string), fields[i+1])
	}
	return d
}

func (fddRuntime) object(fields ...any) *Object { return fdd.obj(fields...).(*Object) }

// orElse is a ?? b (b already evaluated).
func (fddRuntime) orElse(a, b any) any {
	if a != nil {
		return a
	}
	return b
}

// orElseGet is a ?? b (b evaluated only when a is nil).
func (fddRuntime) orElseGet(a any, b func() any) any {
	if a != nil {
		return a
	}
	return b()
}

// eq is a === b for strings, numbers, booleans and nil.
func (fddRuntime) eq(a, b any) bool {
	switch x := a.(type) {
	case nil:
		return b == nil
	case float64:
		y, ok := b.(float64)
		return ok && x == y
	case string:
		y, ok := b.(string)
		return ok && x == y
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case *Object:
		y, ok := b.(*Object)
		return ok && x == y
	}
	return false
}

func (fddRuntime) iter(v any) []any {
	if l, ok := v.([]any); ok {
		return l
	}
	return nil
}

func (fddRuntime) mapItems(items any, fn func(x, i any) any) any {
	list := fdd.iter(items)
	out := make([]any, 0, len(list))
	for i, x := range list {
		out = append(out, fn(x, float64(i)))
	}
	return out
}

func (fddRuntime) filterItems(items any, fn func(x, i any) bool) any {
	out := []any{}
	for i, x := range fdd.iter(items) {
		if fn(x, float64(i)) {
			out = append(out, x)
		}
	}
	return out
}

func (fddRuntime) findItem(items any, fn func(x, i any) bool) any {
	for i, x := range fdd.iter(items) {
		if fn(x, float64(i)) {
			return x
		}
	}
	return nil
}

func (fddRuntime) someItem(items any, fn func(x, i any) bool) bool {
	for i, x := range fdd.iter(items) {
		if fn(x, float64(i)) {
			return true
		}
	}
	return false
}

func (fddRuntime) everyItem(items any, fn func(x, i any) bool) bool {
	for i, x := range fdd.iter(items) {
		if !fn(x, float64(i)) {
			return false
		}
	}
	return true
}

func (fddRuntime) key(o any, k any) any {
	switch d := o.(type) {
	case *Object:
		s, ok := k.(string)
		if !ok {
			s = fdd.jsString(k)
		}
		v, _ := d.Get(s)
		return v
	case []any:
		if k == "length" {
			return float64(len(d))
		}
		if i := index(k); i >= 0 && i < len(d) {
			return d[i]
		}
	case string:
		if k == "length" {
			return float64(len(units(d)))
		}
		u := units(d)
		if j := index(k); j >= 0 && j < len(u) {
			return string(utf16.Decode(u[j : j+1]))
		}
	}
	return nil
}

func asciiDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// index is a list position, or -1.
func index(k any) int {
	var d float64
	switch x := k.(type) {
	case float64:
		d = x
	case int:
		d = float64(x)
	case string:
		if !asciiDigits(x) {
			return -1
		}
		d, _ = strconv.ParseFloat(x, 64)
	default:
		return -1
	}
	if d >= 0 && d < math.MaxInt32 && math.Floor(d) == d {
		return int(d)
	}
	return -1
}

// units is a string's UTF-16 code units (JavaScript's string positions).
func units(s string) []uint16 { return utf16.Encode([]rune(s)) }

func fromUnits(u []uint16) string { return string(utf16.Decode(u)) }

func trunc(d float64) float64 { return math.Trunc(d) }

// ---------- JavaScript conversions ----------

// numText writes a number as JavaScript's String(n) does.
func numText(n float64) string {
	switch {
	case math.IsNaN(n):
		return "NaN"
	case math.IsInf(n, 1):
		return "Infinity"
	case math.IsInf(n, -1):
		return "-Infinity"
	case n == 0:
		return "0"
	}
	if math.Abs(n) < 1e15 && math.Floor(n) == n {
		return strconv.FormatInt(int64(n), 10)
	}
	// the shortest digits that read back as the same number, and where the point goes
	e := strconv.FormatFloat(math.Abs(n), 'e', -1, 64)
	mant, exp, _ := strings.Cut(e, "e")
	digits := strings.Replace(mant, ".", "", 1)
	x, _ := strconv.Atoi(exp)
	point := x + 1
	k := len(digits)
	sign := ""
	if n < 0 {
		sign = "-"
	}
	switch {
	case k <= point && point <= 21:
		return sign + digits + strings.Repeat("0", point-k)
	case 0 < point && point <= 21:
		return sign + digits[:point] + "." + digits[point:]
	case -6 < point && point <= 0:
		return sign + "0." + strings.Repeat("0", -point) + digits
	}
	frac := ""
	if k > 1 {
		frac = "." + digits[1:]
	}
	es := "+"
	if point-1 < 0 {
		es = "-"
	}
	return sign + digits[:1] + frac + "e" + es + strconv.Itoa(int(math.Abs(float64(point-1))))
}

// jsString is String(v).
func (fddRuntime) jsString(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case bool:
		if x {
			return "true"
		}
		return "false"
	case float64:
		return numText(x)
	case int:
		return strconv.Itoa(x)
	case string:
		return x
	case []any:
		var sb strings.Builder
		for i, y := range x {
			if i > 0 {
				sb.WriteByte(',')
			}
			if y != nil {
				sb.WriteString(fdd.jsString(y))
			}
		}
		return sb.String()
	case *Object:
		return "[object Object]"
	case error:
		return x.Error()
	}
	return fmt.Sprint(v)
}

// json is JSON.stringify.
func (fddRuntime) json(v any) string {
	var sb strings.Builder
	writeJSON(&sb, v)
	return sb.String()
}

func writeJSON(sb *strings.Builder, v any) {
	switch x := v.(type) {
	case nil:
		sb.WriteString("null")
	case bool:
		sb.WriteString(fdd.jsString(x))
	case float64:
		if math.IsNaN(x) || math.IsInf(x, 0) {
			sb.WriteString("null")
		} else {
			sb.WriteString(numText(x))
		}
	case int:
		sb.WriteString(strconv.Itoa(x))
	case string:
		quoteJSON(sb, x)
	case []any:
		sb.WriteByte('[')
		for i, y := range x {
			if i > 0 {
				sb.WriteByte(',')
			}
			writeJSON(sb, y)
		}
		sb.WriteByte(']')
	case *Object:
		sb.WriteByte('{')
		for i, k := range x.Keys() {
			if i > 0 {
				sb.WriteByte(',')
			}
			quoteJSON(sb, k)
			sb.WriteByte(':')
			y, _ := x.Get(k)
			writeJSON(sb, y)
		}
		sb.WriteByte('}')
	default:
		quoteJSON(sb, fmt.Sprint(v))
	}
}

func quoteJSON(sb *strings.Builder, s string) {
	sb.WriteByte('"')
	for _, c := range s {
		switch c {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		default:
			if c < 0x20 {
				fmt.Fprintf(sb, "\\u%04x", c)
			} else {
				sb.WriteRune(c)
			}
		}
	}
	sb.WriteByte('"')
}

// jsSpace is JavaScript's white space and line terminators (what String.prototype.trim removes).
func jsSpace(c rune) bool {
	return c == ' ' || (c >= 0x09 && c <= 0x0d) || c == 0xa0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200a) || c == 0x2028 || c == 0x2029 ||
		c == 0x202f || c == 0x205f || c == 0x3000 || c == 0xfeff
}

func jsTrim(s string) string { return strings.TrimFunc(s, jsSpace) }

var decimalText = regexp.MustCompile("^[+-]?(\\d+\\.?\\d*|\\.\\d+)([eE][+-]?\\d+)?$")

// jsNumber is Number(v).
func (fddRuntime) jsNumber(v any) float64 {
	switch x := v.(type) {
	case nil:
		return 0
	case bool:
		if x {
			return 1
		}
		return 0
	case float64:
		return x
	case int:
		return float64(x)
	case string:
		t := jsTrim(x)
		if t == "" {
			return 0
		}
		if len(t) > 2 && t[0] == '0' && strings.ContainsRune("xXoObB", rune(t[1])) {
			radix := map[byte]float64{'x': 16, 'X': 16, 'o': 8, 'O': 8, 'b': 2, 'B': 2}[t[1]]
			acc := 0.0
			for _, c := range t[2:] {
				d := strings.IndexRune("0123456789abcdefghijklmnopqrstuvwxyz", c|0x20)
				if c > 'z' || d < 0 || float64(d) >= radix {
					return math.NaN()
				}
				acc = acc*radix + float64(d)
			}
			return acc
		}
		switch t {
		case "Infinity", "+Infinity":
			return math.Inf(1)
		case "-Infinity":
			return math.Inf(-1)
		}
		if !decimalText.MatchString(t) {
			return math.NaN()
		}
		f, _ := strconv.ParseFloat(t, 64)
		return f
	case []any:
		if len(x) == 0 {
			return 0
		}
		if len(x) == 1 {
			switch x[0].(type) {
			case []any, *Object:
				return math.NaN()
			case nil:
				return 0
			}
			return fdd.jsNumber(x[0])
		}
	}
	return math.NaN()
}

func prim(x any) any {
	switch x.(type) {
	case []any, *Object:
		return fdd.jsString(x)
	}
	return x
}

func compareUnits(a, b string) int {
	u, w := units(a), units(b)
	for i := 0; i < len(u) && i < len(w); i++ {
		if u[i] != w[i] {
			if u[i] < w[i] {
				return -1
			}
			return 1
		}
	}
	return len(u) - len(w)
}

func lt(a, b any) bool {
	s, ok1 := a.(string)
	t, ok2 := b.(string)
	if ok1 && ok2 {
		return compareUnits(s, t) < 0
	}
	return fdd.jsNumber(prim(a)) < fdd.jsNumber(prim(b))
}

// ---------- values ----------

// truthy is branch semantics: "" and "false" are false.
func (fddRuntime) truthy(v any) bool {
	switch x := v.(type) {
	case nil:
		return false
	case string:
		return x != "" && x != "false"
	case bool:
		return x
	case float64:
		return x != 0 && !math.IsNaN(x)
	}
	return true
}

// isEmpty: nil, "", [] or {}.
func (fddRuntime) isEmpty(v any) bool {
	switch x := v.(type) {
	case nil:
		return true
	case string:
		return jsTrim(x) == ""
	case []any:
		return len(x) == 0
	case *Object:
		return x.Len() == 0
	}
	return false
}

// isNull: nil or missing.
func (fddRuntime) isNull(v any) bool { return v == nil }

// deepEqual is structural equality (objects and arrays by value).
func (fddRuntime) deepEqual(a, b any) bool {
	switch x := a.(type) {
	case float64:
		y, ok := b.(float64)
		return ok && (x == y || (math.IsNaN(x) && math.IsNaN(y)))
	case []any:
		y, ok := b.([]any)
		if !ok || len(x) != len(y) {
			return false
		}
		for i := range x {
			if !fdd.deepEqual(x[i], y[i]) {
				return false
			}
		}
		return true
	case *Object:
		y, ok := b.(*Object)
		if !ok || x.Len() != y.Len() {
			return false
		}
		for _, k := range x.keys {
			w, has := y.Get(k)
			if !has || !fdd.deepEqual(x.vals[k], w) {
				return false
			}
		}
		return true
	}
	return fdd.eq(a, b)
}

// compare gives -1, 0 or 1.
func (fddRuntime) compare(a, b any) float64 {
	if fdd.deepEqual(a, b) {
		return 0
	}
	if lt(a, b) {
		return -1
	}
	return 1
}

// toNum is an arithmetic operand: numbers as is, anything else through Number().
func (fddRuntime) toNum(v any) float64 {
	if f, ok := v.(float64); ok {
		return f
	}
	return fdd.jsNumber(v)
}

// mod is JavaScript's %.
func (fddRuntime) mod(a, b float64) float64 { return math.Mod(a, b) }

// divide fails on zero.
func (fddRuntime) divide(a, b any) float64 {
	if fdd.toNum(b) == 0 {
		panic(&FddError{"DIVIDE_BY_ZERO", "Division by zero"})
	}
	return fdd.toNum(a) / fdd.toNum(b)
}

// asArray is the value if it is an array, else [].
func (fddRuntime) asArray(v any) []any {
	if l, ok := v.([]any); ok {
		return l
	}
	return []any{}
}

func asObject(v any) *Object {
	if o, ok := v.(*Object); ok {
		return o
	}
	return NewObject()
}

// isFound: a query found something (not nil, not an empty list).
func (fddRuntime) isFound(v any) bool {
	if l, ok := v.([]any); ok {
		return len(l) > 0
	}
	return v != nil
}

// omitNulls drops nil entries (query and header maps).
func (fddRuntime) omitNulls(o any) any {
	out := NewObject()
	src := asObject(o)
	for _, k := range src.keys {
		if v := src.vals[k]; v != nil {
			out.Set(k, v)
		}
	}
	return out
}

// ---------- paths & objects ----------

type pathSeg struct {
	name  string
	index int
	isIdx bool
}

var segmentRe = regexp.MustCompile("([^\\[\\]]+)|\\[(\\d+)\\]")

// pathSegments: user.roles[0].name.
func pathSegments(path string) []pathSeg {
	var out []pathSeg
	for _, part := range strings.Split(path, ".") {
		if part == "" {
			continue
		}
		for _, m := range segmentRe.FindAllStringSubmatch(part, -1) {
			if m[1] != "" {
				out = append(out, pathSeg{name: m[1]})
			} else {
				n, err := strconv.Atoi(m[2])
				if err != nil {
					n = math.MaxInt32
				}
				out = append(out, pathSeg{index: n, isIdx: true})
			}
		}
	}
	return out
}

func unsafePath(segs []pathSeg) bool {
	for _, s := range segs {
		if !s.isIdx && (s.name == "__proto__" || s.name == "constructor" || s.name == "prototype") {
			return true
		}
	}
	return false
}

func (s pathSeg) value() any {
	if s.isIdx {
		return float64(s.index)
	}
	return s.name
}

func (s pathSeg) key() string {
	if s.isIdx {
		return strconv.Itoa(s.index)
	}
	return s.name
}

// hasPath: the path exists (its value may be nil).
func (fddRuntime) hasPath(value any, path any) bool {
	p := fdd.str(path)
	if p == "" || p == "$" {
		return true
	}
	segs := pathSegments(p)
	if unsafePath(segs) {
		return false
	}
	cur := value
	for _, s := range segs {
		switch d := cur.(type) {
		case *Object:
			v, ok := d.Get(s.key())
			if !ok {
				return false
			}
			cur = v
		case []any:
			if !s.isIdx && s.name == "length" {
				cur = float64(len(d))
			} else if s.isIdx && s.index < len(d) {
				cur = d[s.index]
			} else {
				return false
			}
		case string:
			u := units(d)
			if !s.isIdx && s.name == "length" {
				cur = float64(len(u))
			} else if s.isIdx && s.index < len(u) {
				cur = fromUnits(u[s.index : s.index+1])
			} else {
				return false
			}
		default:
			return false
		}
	}
	return true
}

// getPath reads a nested value; nil when a step is missing.
func (fddRuntime) getPath(value any, path any) any {
	p := fdd.str(path)
	if p == "" || p == "$" {
		return value
	}
	segs := pathSegments(p)
	if unsafePath(segs) {
		return nil
	}
	cur := value
	for _, s := range segs {
		if cur == nil {
			return nil
		}
		cur = fdd.key(cur, s.value())
	}
	return cur
}

func lookup(value any, path string) any {
	if fdd.hasPath(value, path) {
		return fdd.getPath(value, path)
	}
	return missing
}

func container(v any) bool {
	switch v.(type) {
	case []any, *Object:
		return true
	}
	return false
}

func shallowCopy(v any) any {
	switch x := v.(type) {
	case []any:
		return append([]any{}, x...)
	case *Object:
		o := NewObject()
		for _, k := range x.keys {
			o.Set(k, x.vals[k])
		}
		return o
	}
	return v
}

func emptyFor(next pathSeg) any {
	if next.isIdx {
		return []any{}
	}
	return NewObject()
}

// setPath makes a copy with a nested value set.
func (fddRuntime) setPath(value any, path any, v any) any {
	segs := pathSegments(fdd.str(path))
	if len(segs) == 0 {
		return v
	}
	var root any = NewObject()
	if container(value) {
		root = shallowCopy(value)
	}
	if unsafePath(segs) {
		return root
	}
	return setIn(root, segs, 0, v)
}

// setIn sets segs[i:] in cur, a fresh copy, and returns it.
func setIn(cur any, segs []pathSeg, i int, v any) any {
	s, last := segs[i], i == len(segs)-1
	if l, ok := cur.([]any); ok {
		if !s.isIdx {
			return l
		}
		for len(l) <= s.index {
			l = append(l, nil)
		}
		if last {
			if v != missing {
				l[s.index] = v
			}
			return l
		}
		next := shallowCopy(l[s.index])
		if !container(next) {
			next = emptyFor(segs[i+1])
		}
		l[s.index] = setIn(next, segs, i+1, v)
		return l
	}
	d := cur.(*Object)
	k := s.key()
	if last {
		if v != missing {
			d.Set(k, v)
		}
		return d
	}
	var next any
	if c, ok := d.Get(k); ok {
		next = shallowCopy(c)
	}
	if !container(next) {
		next = emptyFor(segs[i+1])
	}
	d.Set(k, setIn(next, segs, i+1, v))
	return d
}

func deepClone(v any) any {
	switch x := v.(type) {
	case []any:
		out := make([]any, len(x))
		for i, y := range x {
			out[i] = deepClone(y)
		}
		return out
	case *Object:
		o := NewObject()
		for _, k := range x.keys {
			o.Set(k, deepClone(x.vals[k]))
		}
		return o
	}
	return v
}

// removePath makes a copy without a nested value.
func (fddRuntime) removePath(value any, path any) any {
	segs := pathSegments(fdd.str(path))
	if len(segs) == 0 || !container(value) {
		return value
	}
	clone := deepClone(value)
	if unsafePath(segs) {
		return clone
	}
	return removeIn(clone, segs)
}

func removeIn(cur any, segs []pathSeg) any {
	s := segs[0]
	if len(segs) == 1 {
		switch d := cur.(type) {
		case []any:
			if s.isIdx && s.index < len(d) {
				return append(d[:s.index:s.index], d[s.index+1:]...)
			}
		case *Object:
			d.Delete(s.key())
		}
		return cur
	}
	switch d := cur.(type) {
	case *Object:
		if next, ok := d.Get(s.key()); ok && container(next) {
			d.Set(s.key(), removeIn(next, segs[1:]))
		}
	case []any:
		if s.isIdx && s.index < len(d) && container(d[s.index]) {
			d[s.index] = removeIn(d[s.index], segs[1:])
		}
	}
	return cur
}

func spread(v any) *Object {
	switch x := v.(type) {
	case *Object:
		return x
	case []any:
		out := NewObject()
		for i, y := range x {
			out.Set(strconv.Itoa(i), y)
		}
		return out
	case string:
		out := NewObject()
		for i, u := range units(x) {
			out.Set(strconv.Itoa(i), fromUnits([]uint16{u}))
		}
		return out
	}
	return NewObject()
}

// merge is a shallow merge, B over A.
func (fddRuntime) merge(a, b any) any {
	d := NewObject()
	for _, src := range []*Object{spread(a), spread(b)} {
		for _, k := range src.keys {
			d.Set(k, src.vals[k])
		}
	}
	return d
}

// transform makes a new object: target path from source path.
func (fddRuntime) transform(source any, mapping any) any {
	var out any = NewObject()
	for _, pair := range fdd.asArray(mapping) {
		p := fdd.asArray(pair)
		var target, from any
		if len(p) > 0 {
			target = p[0]
		}
		if len(p) > 1 {
			from = p[1]
		}
		out = fdd.setPath(out, target, lookup(source, fdd.str(from)))
	}
	return out
}

var placeholderRe = regexp.MustCompile("\\{\\{\\s*([^}]+?)\\s*\\}\\}")
var wholePlaceholderRe = regexp.MustCompile("^\\{\\{\\s*([^}]+?)\\s*\\}\\}$")

// template fills {{path}} placeholders from data.
func (fddRuntime) template(value any, data any) any {
	r := fill(value, data)
	if r == missing {
		return nil
	}
	return r
}

func fill(value any, data any) any {
	switch x := value.(type) {
	case string:
		if m := wholePlaceholderRe.FindStringSubmatch(x); m != nil {
			return lookup(data, m[1])
		}
		return placeholderRe.ReplaceAllStringFunc(x, func(s string) string {
			r := fdd.getPath(data, placeholderRe.FindStringSubmatch(s)[1])
			if r == nil {
				return ""
			}
			if container(r) {
				return fdd.json(r)
			}
			return fdd.jsString(r)
		})
	case []any:
		out := make([]any, len(x))
		for i, y := range x {
			if z := fill(y, data); z != missing {
				out[i] = z
			}
		}
		return out
	case *Object:
		o := NewObject()
		for _, k := range x.keys {
			if z := fill(x.vals[k], data); z != missing {
				o.Set(k, z)
			}
		}
		return o
	}
	return value
}

// parseJson is JSON.parse that fails with INVALID_JSON.
func (fddRuntime) parseJson(text any) any {
	v, err := ParseJSON(fdd.jsString(text))
	if err != nil {
		panic(&FddError{"INVALID_JSON", "Not valid JSON"})
	}
	return v
}

// toError is the { code, message } a Catch or Failed pin receives.
func (fddRuntime) toError(e any) any {
	var f *FddError
	if err, ok := e.(error); ok && errors.As(err, &f) {
		return fdd.obj("code", f.Code, "message", f.Message)
	}
	return fdd.obj("code", "RUNTIME_ERROR", "message", fdd.jsString(e))
}

// ---------- strings ----------

// str is a string operand: nil is "".
func (fddRuntime) str(v any) string {
	if v == nil {
		return ""
	}
	return fdd.jsString(v)
}

// asString is String(v), like a Switch compares.
func (fddRuntime) asString(v any) string { return fdd.jsString(v) }

func (fddRuntime) contains(text, search any) bool {
	return strings.Contains(fdd.str(text), fdd.str(search))
}

func (fddRuntime) startsWith(text, prefix any) bool {
	return strings.HasPrefix(fdd.str(text), fdd.str(prefix))
}

func (fddRuntime) endsWith(text, suffix any) bool {
	return strings.HasSuffix(fdd.str(text), fdd.str(suffix))
}

func (fddRuntime) trim(text any) string { return jsTrim(fdd.str(text)) }

func (fddRuntime) lower(text any) string { return strings.ToLower(fdd.str(text)) }

func (fddRuntime) upper(text any) string {
	return strings.ReplaceAll(strings.ToUpper(fdd.str(text)), "ß", "SS")
}

func (fddRuntime) strLength(text any) float64 { return float64(len(units(fdd.str(text)))) }

func (fddRuntime) concat(a, b any) string { return fdd.str(a) + fdd.str(b) }

func (fddRuntime) replaceAll(text, search, replacement any) string {
	t, s, r := fdd.str(text), fdd.str(search), fdd.str(replacement)
	if s != "" {
		return strings.ReplaceAll(t, s, r)
	}
	var sb strings.Builder
	for i, c := range []rune(t) {
		if i > 0 {
			sb.WriteString(r)
		}
		sb.WriteRune(c)
	}
	return sb.String()
}

// split: an empty separator splits on ",".
func (fddRuntime) split(text, separator any) any {
	sep := fdd.str(separator)
	if sep == "" {
		sep = ","
	}
	parts := strings.Split(fdd.str(text), sep)
	out := make([]any, len(parts))
	for i, p := range parts {
		out[i] = p
	}
	return out
}

func (fddRuntime) join(items, separator any) string {
	l := fdd.asArray(items)
	parts := make([]string, len(l))
	for i, x := range l {
		parts[i] = fdd.str(x)
	}
	return strings.Join(parts, fdd.str(separator))
}

// rx compiles a JavaScript pattern with its flags. Go's regular expressions have no lookarounds or backreferences:
// a pattern that needs them fails.
func rx(pattern, flags string) (*regexp.Regexp, error) {
	prefix := ""
	for _, c := range flags {
		if !strings.ContainsRune("gimsuyd", c) {
			return nil, fmt.Errorf("invalid flags %q", flags)
		}
		if c == 'i' || c == 'm' || c == 's' {
			prefix += string(c)
		}
	}
	if prefix != "" {
		pattern = "(?" + prefix + ")" + pattern
	}
	return regexp.Compile(pattern)
}

func (fddRuntime) regexMatch(text, pattern, flags any) any {
	re, err := rx(fdd.str(pattern), fdd.str(flags))
	if err != nil {
		panic(&FddError{"INVALID_REGEX", "Invalid pattern " + fdd.str(pattern)})
	}
	t := fdd.str(text)
	m := re.FindStringSubmatchIndex(t)
	groups := []any{}
	if m != nil {
		for i := 2; i+1 < len(m); i += 2 {
			if m[i] < 0 {
				groups = append(groups, nil)
			} else {
				groups = append(groups, t[m[i]:m[i+1]])
			}
		}
	}
	return fdd.obj("matches", m != nil, "groups", groups)
}

var namedRe = regexp.MustCompile("\\{(\\w+)\\}")

// format fills {name} placeholders.
func (fddRuntime) format(template, values any) string {
	return namedRe.ReplaceAllStringFunc(fdd.str(template), func(s string) string {
		return fdd.str(fdd.get(values, s[1:len(s)-1]))
	})
}

// ---------- collections ----------

func (fddRuntime) len(a any) float64 {
	if l, ok := a.([]any); ok {
		return float64(len(l))
	}
	return 0
}

func (fddRuntime) at(a, i any) any { return fdd.key(fdd.asArray(a), fdd.toNum(i)) }

// append makes a copy with the item appended.
func (fddRuntime) append(a, item any) any {
	return append(append([]any{}, fdd.asArray(a)...), item)
}

// includes is deep-equal membership.
func (fddRuntime) includes(a, item any) bool {
	for _, x := range fdd.asArray(a) {
		if fdd.deepEqual(x, item) {
			return true
		}
	}
	return false
}

func (fddRuntime) sum(a, path any) float64 {
	t := 0.0
	p := fdd.str(path)
	for _, x := range fdd.asArray(a) {
		if p != "" {
			x = fdd.getPath(x, p)
		}
		t += fdd.toNum(x)
	}
	return t
}

func (fddRuntime) sortBy(a, path, desc any) any {
	dir := 1
	if fdd.truthy(desc) {
		dir = -1
	}
	p := fdd.str(path)
	items := append([]any{}, fdd.asArray(a)...)
	// a stable merge sort, like Array.prototype.sort
	mergeSort(items, func(x, y any) int {
		u, w := x, y
		if p != "" {
			u, w = fdd.getPath(x, p), fdd.getPath(y, p)
		}
		if lt(u, w) {
			return -dir
		}
		if lt(w, u) {
			return dir
		}
		return 0
	})
	return items
}

func mergeSort(l []any, c func(x, y any) int) {
	if len(l) < 2 {
		return
	}
	mid := len(l) / 2
	a, b := append([]any{}, l[:mid]...), append([]any{}, l[mid:]...)
	mergeSort(a, c)
	mergeSort(b, c)
	i, j, k := 0, 0, 0
	for i < len(a) && j < len(b) {
		if c(b[j], a[i]) < 0 {
			l[k] = b[j]
			j++
		} else {
			l[k] = a[i]
			i++
		}
		k++
	}
	for ; i < len(a); i, k = i+1, k+1 {
		l[k] = a[i]
	}
	for ; j < len(b); j, k = j+1, k+1 {
		l[k] = b[j]
	}
}

// mapAsync maps one item at a time (deterministic order).
func (fddRuntime) mapAsync(items any, fn func(x, i any) any) any { return fdd.mapItems(items, fn) }

func (fddRuntime) filterAsync(items any, fn func(x, i any) any) any {
	return fdd.filterItems(items, func(x, i any) bool { return fdd.truthy(fn(x, i)) })
}

func (fddRuntime) findAsync(items any, fn func(x, i any) any) any {
	return fdd.findItem(items, func(x, i any) bool { return fdd.truthy(fn(x, i)) })
}

func (fddRuntime) someAsync(items any, fn func(x, i any) any) bool {
	return fdd.someItem(items, func(x, i any) bool { return fdd.truthy(fn(x, i)) })
}

func (fddRuntime) everyAsync(items any, fn func(x, i any) any) bool {
	return fdd.everyItem(items, func(x, i any) bool { return fdd.truthy(fn(x, i)) })
}

// first is the first item, or nil.
func (fddRuntime) first(a any) any {
	if l := fdd.asArray(a); len(l) > 0 {
		return l[0]
	}
	return nil
}

// last is the last item, or nil.
func (fddRuntime) last(a any) any {
	if l := fdd.asArray(a); len(l) > 0 {
		return l[len(l)-1]
	}
	return nil
}

// groupBy groups items by the text of a path: { value: [items] }.
func (fddRuntime) groupBy(a, path any) any {
	p := fdd.str(path)
	groups := NewObject()
	for _, x := range fdd.asArray(a) {
		v := x
		if p != "" {
			v = fdd.getPath(x, p)
		}
		k := fdd.toStringValue(v)
		cur, _ := groups.Get(k)
		groups.Set(k, append(fdd.asArray(cur), x))
	}
	return groups
}

// average is the mean of numbers or of a path; 0 for an empty list.
func (fddRuntime) average(a, path any) float64 {
	n := len(fdd.asArray(a))
	if n == 0 {
		return 0
	}
	return fdd.sum(a, path) / float64(n)
}

// ---------- validation: every check returns { valid, message } ----------

func valid() any { return fdd.obj("valid", true, "message", "") }

func invalid(message string) any { return fdd.obj("valid", false, "message", message) }

func (fddRuntime) checkRequired(v, field any) any {
	if fdd.isEmpty(v) {
		return invalid(fdd.str(field) + " is required")
	}
	return valid()
}

// emailLike is /^[^@\s]+@[^@\s]+\.[^@\s]+$/.
func emailLike(s string) bool {
	if strings.IndexFunc(s, jsSpace) >= 0 || strings.Count(s, "@") != 1 {
		return false
	}
	local, domain, _ := strings.Cut(s, "@")
	if local == "" {
		return false
	}
	d := units(domain)
	for i := 1; i < len(d)-1; i++ {
		if d[i] == '.' {
			return true
		}
	}
	return false
}

func (fddRuntime) checkEmail(v, field any) any {
	if s, ok := v.(string); ok && emailLike(s) {
		return valid()
	}
	return invalid(fdd.str(field) + " must be a valid email")
}

func valueType(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case []any:
		return "array"
	case float64:
		if !math.IsInf(x, 0) && !math.IsNaN(x) && math.Floor(x) == x {
			return "integer"
		}
		return "number"
	case string:
		return "string"
	case bool:
		return "boolean"
	}
	return "object"
}

func (fddRuntime) checkType(v, typ, field any) any {
	vt, t := valueType(v), fdd.str(typ)
	if vt == t || (t == "number" && vt == "integer") {
		return valid()
	}
	return invalid(fdd.str(field) + " must be " + t)
}

// checkValue is the first problem of a value against a shape, or "".
func checkValue(v, s any, path string) string {
	shape, ok := s.(*Object)
	if !ok || fdd.eq(fdd.get(s, "type"), "any") {
		return ""
	}
	typ := fdd.get(shape, "type")
	if v == nil {
		if fdd.truthy(fdd.get(shape, "nullable")) || fdd.eq(typ, "null") {
			return ""
		}
		return path + " is null"
	}
	t := valueType(v)
	if fdd.eq(typ, "number") && (t == "integer" || t == "number") {
		return ""
	}
	if !fdd.eq(typ, t) {
		return path + ": expected " + fdd.str(typ) + ", got " + t
	}
	if en, ok := fdd.get(shape, "enum").([]any); ok && len(en) > 0 && !fdd.includes(en, v) {
		names := make([]string, len(en))
		for i, x := range en {
			names[i] = fdd.jsString(x)
		}
		return path + ": " + fdd.json(v) + " is not one of " + strings.Join(names, ", ")
	}
	if props, ok := fdd.get(shape, "properties").(*Object); ok && t == "object" {
		o := v.(*Object)
		for _, k := range props.keys {
			f := props.vals[k]
			child, has := o.Get(k)
			if !has {
				if fdd.truthy(fdd.get(f, "required")) {
					return path + "." + k + " is missing"
				}
				continue
			}
			if p := checkValue(child, f, path+"."+k); p != "" {
				return p
			}
		}
	}
	if l, ok := v.([]any); ok {
		for i, x := range l {
			if p := checkValue(x, fdd.get(shape, "items"), path+"["+strconv.Itoa(i)+"]"); p != "" {
				return p
			}
		}
	}
	return ""
}

func (fddRuntime) checkShape(v, shape, field any) any {
	if p := checkValue(v, shape, fdd.str(field)); p != "" {
		return invalid(p)
	}
	return valid()
}

func (fddRuntime) checkRange(v, lo, hi, field any) any {
	n := fdd.toNum(v)
	if _, ok := v.(float64); !ok {
		return invalid(fdd.str(field) + " must be a number")
	}
	if lo != nil && !fdd.eq(lo, "") && n < fdd.toNum(lo) {
		return invalid(fdd.str(field) + " must be ≥ " + fdd.jsString(lo))
	}
	if hi != nil && !fdd.eq(hi, "") && n > fdd.toNum(hi) {
		return invalid(fdd.str(field) + " must be ≤ " + fdd.jsString(hi))
	}
	return valid()
}

func (fddRuntime) checkRegex(v, pattern, field any) any {
	re, err := rx(fdd.str(pattern), "")
	if err != nil {
		return invalid("invalid pattern")
	}
	if re.MatchString(fdd.str(v)) {
		return valid()
	}
	return invalid(fdd.str(field) + " has an invalid format")
}

func (fddRuntime) checkPassword(v, policy, field any) any {
	p := fdd.str(v)
	if float64(len(units(p))) < fdd.toNum(fdd.get(policy, "minLength")) {
		return invalid(fdd.str(field) + " must be at least " + numText(fdd.toNum(fdd.get(policy, "minLength"))) + " characters")
	}
	if fdd.truthy(fdd.get(policy, "requireDigit")) && !strings.ContainsAny(p, "0123456789") {
		return invalid(fdd.str(field) + " must contain a digit")
	}
	if fdd.truthy(fdd.get(policy, "requireUpper")) && !strings.ContainsAny(p, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") {
		return invalid(fdd.str(field) + " must contain an uppercase letter")
	}
	return valid()
}

// ---------- conversion ----------

// toStringValue: objects become JSON.
func (fddRuntime) toStringValue(v any) string {
	if container(v) {
		return fdd.json(v)
	}
	if v == nil {
		return ""
	}
	return fdd.jsString(v)
}

// toNumber: not a number is 0.
func (fddRuntime) toNumber(v any) float64 {
	n := fdd.jsNumber(v)
	if math.IsNaN(n) {
		return 0
	}
	return n
}

func (fddRuntime) isNumeric(v any) bool { return !math.IsNaN(fdd.jsNumber(v)) }

func (fddRuntime) toBoolean(v any) bool { return fdd.truthy(v) }

// typeOf: string, integer, number, boolean, object, array or null.
func (fddRuntime) typeOf(v any) string { return valueType(v) }

// ---------- math ----------

// round rounds to 0-15 decimals, halves up.
func (fddRuntime) round(v, decimals any) float64 {
	x, d := fdd.toNum(v), trunc(fdd.toNum(decimals))
	if math.IsNaN(d) || math.IsInf(d, 0) {
		d = 0
	}
	f := math.Pow(10, math.Min(15, math.Max(0, d)))
	y := float64(x*f) + 0.5
	if math.IsNaN(y) || math.IsInf(y, 0) {
		return x
	}
	return math.Floor(y) / f
}

func (fddRuntime) floor(v any) float64 { return math.Floor(fdd.toNum(v)) }

func (fddRuntime) ceil(v any) float64 { return math.Ceil(fdd.toNum(v)) }

func (fddRuntime) abs(v any) float64 { return math.Abs(fdd.toNum(v)) }

func jsMin(a, b float64) float64 {
	if math.IsNaN(a) || math.IsNaN(b) {
		return math.NaN()
	}
	return math.Min(a, b)
}

func jsMax(a, b float64) float64 {
	if math.IsNaN(a) || math.IsNaN(b) {
		return math.NaN()
	}
	return math.Max(a, b)
}

func (fddRuntime) min(a, b any) float64 { return jsMin(fdd.toNum(a), fdd.toNum(b)) }

func (fddRuntime) max(a, b any) float64 { return jsMax(fdd.toNum(a), fdd.toNum(b)) }

// clamp keeps the value between lo and hi.
func (fddRuntime) clamp(v, lo, hi any) float64 {
	return jsMin(jsMax(fdd.toNum(v), fdd.toNum(lo)), fdd.toNum(hi))
}

// power is JavaScript's ** (1 ** Infinity is NaN).
func (fddRuntime) power(a, b any) float64 {
	x, y := fdd.toNum(a), fdd.toNum(b)
	return jsPow(x, y)
}

// jsPow is JavaScript's x ** y: IEEE special cases, and otherwise the correctly rounded power (Go's math.Pow can
// differ from JavaScript in the last digit), computed at 128 bits and rounded once.
func jsPow(x, y float64) float64 {
	switch {
	case y == 0:
		return 1
	case math.IsNaN(x) || math.IsNaN(y):
		return math.NaN()
	case math.IsInf(y, 0):
		ax := math.Abs(x)
		switch {
		case ax == 1:
			return math.NaN()
		case (ax > 1) == (y > 0):
			return math.Inf(1)
		}
		return 0
	case y == 1:
		return x
	case y == 2:
		return x * x
	case y == -1:
		return 1 / x
	}
	yInt := math.Trunc(y) == y
	yOdd := yInt && math.Abs(y) < 1<<53 && math.Mod(y, 2) != 0
	if x == 0 || math.IsInf(x, 0) {
		// math.Pow has these right (signs of zero and infinity)
		return math.Pow(x, y)
	}
	if x < 0 && !yInt {
		return math.NaN()
	}
	if y == 0.5 {
		return math.Sqrt(x)
	}
	r := bigPow(math.Abs(x), y)
	if x < 0 && yOdd {
		return -r
	}
	return r
}

const powPrec = 128

func bf(v float64) *big.Float { return new(big.Float).SetPrec(powPrec).SetFloat64(v) }

// atanh2 is 2·atanh(z) = ln((1+z)/(1-z)), for |z| < 0.2.
func atanh2(z *big.Float) *big.Float {
	z2 := new(big.Float).SetPrec(powPrec).Mul(z, z)
	term := new(big.Float).SetPrec(powPrec).Set(z)
	sum := new(big.Float).SetPrec(powPrec).Set(z)
	t := new(big.Float).SetPrec(powPrec)
	for k := 3; k < 200; k += 2 {
		term.Mul(term, z2)
		t.Quo(term, bf(float64(k)))
		if t.Sign() == 0 || t.MantExp(nil)-sum.MantExp(nil) < -powPrec-4 {
			break
		}
		sum.Add(sum, t)
	}
	return sum.Mul(sum, bf(2))
}

var ln2Big = atanh2(new(big.Float).SetPrec(powPrec).Quo(bf(1), bf(3)))

// bigLn is ln(x) for a finite x > 0.
func bigLn(x float64) *big.Float {
	m := new(big.Float).SetPrec(powPrec)
	e := bf(x).MantExp(m) // x = m · 2^e, m in [0.5, 1)
	if m.Cmp(bf(math.Sqrt2/2)) < 0 {
		m.SetMantExp(m, 1)
		e--
	}
	one := bf(1)
	z := new(big.Float).SetPrec(powPrec).Quo(new(big.Float).SetPrec(powPrec).Sub(m, one), new(big.Float).SetPrec(powPrec).Add(m, one))
	r := atanh2(z)
	return r.Add(r, new(big.Float).SetPrec(powPrec).Mul(ln2Big, bf(float64(e))))
}

// bigExp is e^p as a float64, rounded once.
func bigExp(p *big.Float) float64 {
	pf, _ := p.Float64()
	if pf > 710 {
		return math.Inf(1)
	}
	if pf < -746 {
		return 0
	}
	k := math.Round(pf / math.Ln2)
	r := new(big.Float).SetPrec(powPrec).Sub(p, new(big.Float).SetPrec(powPrec).Mul(ln2Big, bf(k)))
	// e^r with r/256, then squared 8 times
	r.SetMantExp(r, -8)
	sum, term, t := bf(1), bf(1), new(big.Float).SetPrec(powPrec)
	for n := 1; n < 60; n++ {
		term.Mul(term, r)
		term.Quo(term, bf(float64(n)))
		if term.Sign() == 0 || term.MantExp(nil) < -powPrec-4 {
			break
		}
		sum.Add(sum, term)
	}
	for i := 0; i < 8; i++ {
		sum.Mul(sum, t.Set(sum))
	}
	sum.SetMantExp(sum, int(k))
	f, _ := sum.Float64()
	return f
}

func bigPow(x, y float64) float64 {
	l := bigLn(x)
	return bigExp(l.Mul(l, bf(y)))
}

func (fddRuntime) sqrt(v any) float64 { return math.Sqrt(fdd.toNum(v)) }

func (fddRuntime) nan() float64 { return math.NaN() }

func (fddRuntime) inf(sign int) float64 { return math.Inf(sign) }

func (fddRuntime) negZero() float64 { return math.Copysign(0, -1) }

// ---------- text and encoding ----------

// relIndex is a slice position: negative counts from the end, clamped to 0..n.
func relIndex(v any, n int) int {
	r := trunc(fdd.toNum(v))
	if math.IsNaN(r) {
		return 0
	}
	if r < 0 {
		return int(math.Max(float64(n)+r, 0))
	}
	return int(math.Min(r, float64(n)))
}

// substring is like String.prototype.slice; a nil end means the end of the text.
func (fddRuntime) substring(text, start, end any) string {
	u := units(fdd.str(text))
	i, j := relIndex(start, len(u)), len(u)
	if end != nil {
		j = relIndex(end, len(u))
	}
	if j <= i {
		return ""
	}
	return fromUnits(u[i:j])
}

func (fddRuntime) indexOf(text, search any) float64 {
	t, s := units(fdd.str(text)), units(fdd.str(search))
	for i := 0; i+len(s) <= len(t); i++ {
		match := true
		for k := range s {
			if t[i+k] != s[k] {
				match = false
				break
			}
		}
		if match {
			return float64(i)
		}
	}
	return -1
}

func padText(text, length, fill any, atStart bool) string {
	t := fdd.str(text)
	n := trunc(fdd.toNum(length))
	if n > 100000 {
		panic(&FddError{"INVALID_LENGTH", "Length must be at most 100000"})
	}
	f := " "
	if fill != nil {
		f = fdd.str(fill)
	}
	tu, fu := units(t), units(f)
	if math.IsNaN(n) || n <= float64(len(tu)) || len(fu) == 0 {
		return t
	}
	need := int(n) - len(tu)
	var pad []uint16
	for len(pad) < need {
		pad = append(pad, fu...)
	}
	if atStart {
		return fromUnits(append(pad[:need:need], tu...))
	}
	return fromUnits(append(tu, pad[:need]...))
}

func (fddRuntime) padStart(text, length, fill any) string { return padText(text, length, fill, true) }

func (fddRuntime) padEnd(text, length, fill any) string { return padText(text, length, fill, false) }

// base64Encode writes UTF-8 text as Base64.
func (fddRuntime) base64Encode(text any) string {
	return base64.StdEncoding.EncodeToString([]byte(fdd.str(text)))
}

var base64Text = regexp.MustCompile("^[A-Za-z0-9+/]*$")
var base64Space = regexp.MustCompile("[\\t\\n\\f\\r ]+")
var base64Pad = regexp.MustCompile("={1,2}$")

// base64Decode reads Base64 as UTF-8 text; fails with INVALID_BASE64.
func (fddRuntime) base64Decode(text any) string {
	t := base64Space.ReplaceAllString(fdd.str(text), "")
	if len(t)%4 == 0 {
		t = base64Pad.ReplaceAllString(t, "")
	}
	if len(t)%4 == 1 || !base64Text.MatchString(t) {
		panic(&FddError{"INVALID_BASE64", "Not valid Base64"})
	}
	b, err := base64.StdEncoding.DecodeString(t + strings.Repeat("=", (4-len(t)%4)%4))
	if err != nil {
		panic(&FddError{"INVALID_BASE64", "Not valid Base64"})
	}
	return strings.ToValidUTF8(string(b), "�")
}

// formatNumber: fixed decimals (halves up) and a thousands separator; fails with INVALID_NUMBER.
func (fddRuntime) formatNumber(value, decimals, thousands, point any) string {
	d0 := trunc(fdd.toNum(decimals))
	d := 0
	if !math.IsNaN(d0) && !math.IsInf(d0, 0) {
		d = int(math.Min(15, math.Max(0, d0)))
	}
	r := fdd.round(value, float64(d))
	if math.IsNaN(r) || math.IsInf(r, 0) || math.Abs(r) >= 1e21 {
		panic(&FddError{"INVALID_NUMBER", "Not a number that can be formatted"})
	}
	text := strconv.FormatFloat(math.Abs(r), 'f', d, 64)
	whole, frac, _ := strings.Cut(text, ".")
	sign := ""
	if r < 0 && strings.ContainsAny(whole+frac, "123456789") {
		sign = "-"
	}
	var groups []string
	for len(whole) > 3 {
		groups = append([]string{whole[len(whole)-3:]}, groups...)
		whole = whole[:len(whole)-3]
	}
	groups = append([]string{whole}, groups...)
	out := sign + strings.Join(groups, fdd.str(thousands))
	if frac != "" {
		out += fdd.str(point) + frac
	}
	return out
}

// digestAlgorithm: sha256, sha1 or md5 ("SHA-256" too); fails with INVALID_ALGORITHM.
func digestAlgorithm(a any) func() hash.Hash {
	switch strings.ReplaceAll(strings.ToLower(jsTrim(fdd.str(a))), "-", "") {
	case "sha256":
		return sha256.New
	case "sha1":
		return sha1.New
	case "md5":
		return md5.New
	}
	panic(&FddError{"INVALID_ALGORITHM", "Unknown hash algorithm \"" + fdd.str(a) + "\" (use sha256, sha1 or md5)"})
}

// encodeDigest: hex or base64; fails with INVALID_ENCODING.
func encodeDigest(b []byte, encoding any) string {
	switch strings.ToLower(jsTrim(fdd.str(encoding))) {
	case "hex":
		return hex.EncodeToString(b)
	case "base64":
		return base64.StdEncoding.EncodeToString(b)
	}
	panic(&FddError{"INVALID_ENCODING", "Unknown encoding \"" + fdd.str(encoding) + "\" (use hex or base64)"})
}

// hash is SHA-256, SHA-1 or MD5 of UTF-8 text, as hex or Base64.
func (fddRuntime) hash(text, algorithm, encoding any) string {
	h := digestAlgorithm(algorithm)()
	h.Write([]byte(fdd.str(text)))
	return encodeDigest(h.Sum(nil), encoding)
}

// hmac is the HMAC of UTF-8 text with a UTF-8 key, as hex or Base64.
func (fddRuntime) hmac(text, key, algorithm, encoding any) string {
	m := hmac.New(digestAlgorithm(algorithm), []byte(fdd.str(key)))
	m.Write([]byte(fdd.str(text)))
	return encodeDigest(m.Sum(nil), encoding)
}

func asciiHex(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// urlEncode is encodeURIComponent.
func (fddRuntime) urlEncode(text any) string {
	var sb strings.Builder
	for _, b := range []byte(fdd.str(text)) {
		if (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') || strings.IndexByte("-_.!~*'()", b) >= 0 {
			sb.WriteByte(b)
		} else {
			fmt.Fprintf(&sb, "%%%02X", b)
		}
	}
	return sb.String()
}

// urlDecode is decodeURIComponent; fails with INVALID_URL_ENCODING.
func (fddRuntime) urlDecode(text any) string {
	s := fdd.str(text)
	var sb strings.Builder
	var buf []byte
	bad := func() { panic(&FddError{"INVALID_URL_ENCODING", "Not valid URL encoding"}) }
	flush := func() {
		if len(buf) > 0 {
			if !utf8.Valid(buf) {
				bad()
			}
			sb.Write(buf)
			buf = buf[:0]
		}
	}
	for i := 0; i < len(s); {
		if s[i] == '%' {
			if i+2 >= len(s) || !asciiHex(s[i+1]) || !asciiHex(s[i+2]) {
				bad()
			}
			n, _ := strconv.ParseUint(s[i+1:i+3], 16, 8)
			buf = append(buf, byte(n))
			i += 3
			continue
		}
		flush()
		sb.WriteByte(s[i])
		i++
	}
	flush()
	return sb.String()
}

// ---------- records and lists ----------

func isIndexKey(k string) bool {
	if k != "0" && (!asciiDigits(k) || k[0] == '0') {
		return false
	}
	f, _ := strconv.ParseFloat(k, 64)
	return f < 4294967295
}

// keys lists field names in JavaScript's order (none for lists and plain values).
func (fddRuntime) keys(o any) any {
	out := []any{}
	if d, ok := o.(*Object); ok {
		for _, k := range d.Keys() {
			out = append(out, k)
		}
	}
	return out
}

func (fddRuntime) values(o any) any {
	out := []any{}
	if d, ok := o.(*Object); ok {
		for _, k := range d.Keys() {
			out = append(out, d.vals[k])
		}
	}
	return out
}

func (fddRuntime) entries(o any) any {
	out := []any{}
	if d, ok := o.(*Object); ok {
		for _, k := range d.Keys() {
			out = append(out, fdd.obj("key", k, "value", d.vals[k]))
		}
	}
	return out
}

// slice is like Array.prototype.slice; a nil end means the end of the list.
func (fddRuntime) slice(a, start, end any) any {
	l := fdd.asArray(a)
	i, j := relIndex(start, len(l)), len(l)
	if end != nil {
		j = relIndex(end, len(l))
	}
	if j <= i {
		return []any{}
	}
	return append([]any{}, l[i:j]...)
}

func (fddRuntime) reverse(a any) any {
	l := fdd.asArray(a)
	out := make([]any, len(l))
	for i, x := range l {
		out[len(l)-1-i] = x
	}
	return out
}

// unique removes deep-equal duplicates, the first kept.
func (fddRuntime) unique(a any) any {
	out := []any{}
	for _, x := range fdd.asArray(a) {
		if !fdd.includes(out, x) {
			out = append(out, x)
		}
	}
	return out
}

// itemIndex is the deep-equal position, or -1.
func (fddRuntime) itemIndex(a, item any) float64 {
	for i, x := range fdd.asArray(a) {
		if fdd.deepEqual(x, item) {
			return float64(i)
		}
	}
	return -1
}

// flatten flattens one level.
func (fddRuntime) flatten(a any) any {
	out := []any{}
	for _, x := range fdd.asArray(a) {
		if l, ok := x.([]any); ok {
			out = append(out, l...)
		} else {
			out = append(out, x)
		}
	}
	return out
}

// ---------- dates: ISO 8601 text in UTC; numbers are epoch milliseconds ----------

const minMs, maxMs, dayMs = int64(-62167219200000), int64(253402300799999), int64(86400000)

var dateText = regexp.MustCompile("^([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[Tt ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\\.([0-9]+))?)?)?(?:([Zz])|([+-])([0-9]{2}):?([0-9]{2}))?$")
var timeUnits = []string{"millisecond", "milliseconds", "ms", "second", "seconds", "minute", "minutes", "hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years"}
var timeUnitMs = []int64{1, 1, 1, 1000, 1000, 60000, 60000, 3600000, 3600000, dayMs, dayMs, 7 * dayMs, 7 * dayMs, -1, -1, -12, -12}
var monthNames = []string{"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}
var dayNames = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
var dateTokens = []string{"yyyy", "yy", "MMMM", "MMM", "MM", "M", "dd", "d", "EEEE", "EEE", "HH", "H", "hh", "h", "mm", "m", "ss", "s", "SSS", "a"}

func floorDiv(a, b int64) int64 {
	q := a / b
	if (a%b != 0) && ((a < 0) != (b < 0)) {
		q--
	}
	return q
}

// daysFromCivil: days since 1970-01-01 (proleptic Gregorian).
func daysFromCivil(y, m, d int64) int64 {
	if m <= 2 {
		y--
	}
	era := floorDiv(y, 400)
	yoe := y - era*400
	mm := m - 3
	if m <= 2 {
		mm = m + 9
	}
	doy := (153*mm+2)/5 + d - 1
	return era*146097 + yoe*365 + yoe/4 - yoe/100 + doy - 719468
}

func civilFromDays(z int64) [3]int64 {
	z += 719468
	era := floorDiv(z, 146097)
	doe := z - era*146097
	yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
	doy := doe - (365*yoe + yoe/4 - yoe/100)
	mp := (5*doy + 2) / 153
	m := mp + 3
	if mp >= 10 {
		m = mp - 9
	}
	y := yoe + era*400
	if m <= 2 {
		y++
	}
	return [3]int64{y, m, doy - (153*mp+2)/5 + 1}
}

func daysIn(y, m int64) int64 {
	if m == 2 {
		if y%4 == 0 && (y%100 != 0 || y%400 == 0) {
			return 29
		}
		return 28
	}
	if m == 4 || m == 6 || m == 9 || m == 11 {
		return 30
	}
	return 31
}

// dateMs is the epoch milliseconds of a date (years 0-9999); ok is false when it isn't one.
func dateMs(v any) (int64, bool) {
	var ms int64
	switch x := v.(type) {
	case float64:
		if math.IsNaN(x) || math.IsInf(x, 0) || trunc(x) < float64(minMs) || trunc(x) > float64(maxMs) {
			return 0, false
		}
		ms = int64(trunc(x))
	case string:
		m := dateText.FindStringSubmatch(jsTrim(x))
		if m == nil {
			return 0, false
		}
		g := make([]int64, 12)
		for k := 1; k <= 11; k++ {
			if m[k] != "" && k != 7 && k != 8 && k != 9 {
				g[k], _ = strconv.ParseInt(m[k], 10, 64)
			}
		}
		y, mo, d, h, mi, sec := g[1], g[2], g[3], g[4], g[5], g[6]
		if mo < 1 || mo > 12 || d < 1 || d > daysIn(y, mo) || h > 23 || mi > 59 || sec > 59 {
			return 0, false
		}
		tz := m[9] != ""
		if tz && (g[10] > 23 || g[11] > 59) {
			return 0, false
		}
		off := int64(0)
		if tz {
			off = g[10]*60 + g[11]
		}
		frac, _ := strconv.ParseInt((m[7] + "000")[:3], 10, 64)
		if m[9] == "-" {
			off = -off
		}
		ms = (daysFromCivil(y, mo, d)*86400+h*3600+mi*60+sec)*1000 + frac - off*60000
	default:
		return 0, false
	}
	if ms >= minMs && ms <= maxMs {
		return ms, true
	}
	return 0, false
}

func needDate(v any) int64 {
	ms, ok := dateMs(v)
	if !ok {
		panic(&FddError{"INVALID_DATE", "Not a valid date"})
	}
	return ms
}

// dateFields: [year, month, day, hour, minute, second, millisecond, weekday (0 = Sunday), time of day].
func dateFields(ms int64) [9]int64 {
	days := floorDiv(ms, dayMs)
	t := ms - days*dayMs
	c := civilFromDays(days)
	return [9]int64{c[0], c[1], c[2], t / 3600000, t / 60000 % 60, t / 1000 % 60, t % 1000, (days%7 + 11) % 7, t}
}

func isoDate(ms float64) string {
	if !(ms >= float64(minMs) && ms <= float64(maxMs)) {
		panic(&FddError{"INVALID_DATE", "The date is out of range"})
	}
	p := dateFields(int64(ms))
	return fmt.Sprintf("%04d-%02d-%02dT%02d:%02d:%02d.%03dZ", p[0], p[1], p[2], p[3], p[4], p[5], p[6])
}

// timeUnit is the milliseconds of a unit; months are -1 and years -12.
func timeUnit(u any) int64 {
	k := strings.ToLower(jsTrim(fdd.str(u)))
	for i, n := range timeUnits {
		if n == k {
			return timeUnitMs[i]
		}
	}
	panic(&FddError{"INVALID_UNIT", "Unknown time unit \"" + fdd.str(u) + "\""})
}

// parseDate is a date as UTC date-time text and epoch milliseconds.
func (fddRuntime) parseDate(v any) any {
	ms, ok := dateMs(v)
	if !ok {
		return fdd.obj("date", nil, "timestamp", nil, "valid", false)
	}
	return fdd.obj("date", isoDate(float64(ms)), "timestamp", float64(ms), "valid", true)
}

func zpad(n int64, w int) string {
	s := strconv.FormatInt(n, 10)
	if len(s) >= w {
		return s
	}
	return strings.Repeat("0", w-len(s)) + s
}

// formatDate: yyyy yy MMMM MMM MM M dd d EEEE EEE HH H hh h mm m ss s SSS a; text in single quotes is kept as is, and two single quotes are one.
func (fddRuntime) formatDate(date, pattern any) string {
	p := dateFields(needDate(date))
	f := units(fdd.str(pattern))
	h12 := p[3] % 12
	if h12 == 0 {
		h12 = 12
	}
	month, day := monthNames[p[1]-1], dayNames[p[7]]
	ampm := "PM"
	if p[3] < 12 {
		ampm = "AM"
	}
	values := []string{zpad(p[0], 4), zpad(p[0]%100, 2), month, month[:3], zpad(p[1], 2), zpad(p[1], 1), zpad(p[2], 2), zpad(p[2], 1), day, day[:3],
		zpad(p[3], 2), zpad(p[3], 1), zpad(h12, 2), zpad(h12, 1), zpad(p[4], 2), zpad(p[4], 1), zpad(p[5], 2), zpad(p[5], 1), zpad(p[6], 3), ampm}
	var out []uint16
	at := func(i int) uint16 {
		if i < len(f) {
			return f[i]
		}
		return 0
	}
	for i := 0; i < len(f); {
		if f[i] == '\'' {
			if at(i+1) == '\'' {
				out = append(out, '\'')
				i += 2
				continue
			}
			for i++; i < len(f); i++ {
				if f[i] != '\'' {
					out = append(out, f[i])
				} else if at(i+1) == '\'' {
					out = append(out, f[i])
					i++
				} else {
					break
				}
			}
			i++
			continue
		}
		k := -1
		for t, tok := range dateTokens {
			if len(f)-i >= len(tok) && fromUnits(f[i:i+len(tok)]) == tok {
				k = t
				break
			}
		}
		if k >= 0 {
			out = append(out, units(values[k])...)
			i += len(dateTokens[k])
		} else {
			out = append(out, f[i])
			i++
		}
	}
	return fromUnits(out)
}

// addTime: months and years keep the day, clamped to the end of the month.
func (fddRuntime) addTime(date, amount, unit any) string {
	ms := needDate(date)
	u := timeUnit(unit)
	n := fdd.toNum(amount)
	if math.IsNaN(n) || math.IsInf(n, 0) {
		panic(&FddError{"INVALID_DATE", "The date is out of range"})
	}
	if u > 0 {
		return isoDate(float64(ms) + math.Floor(float64(n*float64(u))+0.5))
	}
	if math.Abs(trunc(n)) > 1e6 {
		panic(&FddError{"INVALID_DATE", "The date is out of range"})
	}
	p := dateFields(ms)
	total := p[0]*12 + p[1] - 1 + int64(trunc(n))*-u
	y := floorDiv(total, 12)
	m := total - y*12 + 1
	day := p[2]
	if dm := daysIn(y, m); dm < day {
		day = dm
	}
	return isoDate(float64(daysFromCivil(y, m, day)*dayMs + p[8]))
}

// timeBetween: whole units from From to To, toward zero.
func (fddRuntime) timeBetween(from, to, unit any) float64 {
	a, b, u := needDate(from), needDate(to), timeUnit(unit)
	if u > 0 {
		return trunc(float64(b-a)/float64(u)) + 0
	}
	p, q := dateFields(a), dateFields(b)
	months := (q[0]-p[0])*12 + q[1] - p[1]
	if months > 0 && (q[2] < p[2] || (q[2] == p[2] && q[8] < p[8])) {
		months--
	} else if months < 0 && (q[2] > p[2] || (q[2] == p[2] && q[8] > p[8])) {
		months++
	}
	return trunc(float64(months)/float64(-u)) + 0
}

// dateParts: year ... millisecond in UTC, weekday 1 = Monday ... 7 = Sunday.
func (fddRuntime) dateParts(date any) any {
	p := dateFields(needDate(date))
	wd := p[7]
	if wd == 0 {
		wd = 7
	}
	return fdd.obj("year", float64(p[0]), "month", float64(p[1]), "day", float64(p[2]), "hour", float64(p[3]), "minute", float64(p[4]),
		"second", float64(p[5]), "millisecond", float64(p[6]), "weekday", float64(wd))
}

// makeDate is a UTC date-time from its parts; fails with INVALID_DATE.
func (fddRuntime) makeDate(year, month, day, hour, minute, second any) string {
	v := []float64{fdd.toNum(year), fdd.toNum(month), fdd.toNum(day), fdd.toNum(hour), fdd.toNum(minute), fdd.toNum(second)}
	for _, x := range v {
		if math.IsNaN(x) || math.IsInf(x, 0) || math.Floor(x) != x {
			panic(&FddError{"INVALID_DATE", "Not a valid date"})
		}
	}
	y, m, d, h, mi, s := int64(v[0]), int64(v[1]), int64(v[2]), int64(v[3]), int64(v[4]), int64(v[5])
	if y < 0 || y > 9999 || m < 1 || m > 12 || d < 1 || d > daysIn(y, m) || h < 0 || h > 23 || mi < 0 || mi > 59 || s < 0 || s > 59 {
		panic(&FddError{"INVALID_DATE", "Not a valid date"})
	}
	return isoDate(float64((daysFromCivil(y, m, d)*86400 + h*3600 + mi*60 + s) * 1000))
}

var periods = []string{"hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years"}

// periodEdge: the first (or last) millisecond of the hour, day, week from Monday, month or year.
func periodEdge(date, unit any, end bool) string {
	ms := needDate(date)
	p := dateFields(ms)
	day := floorDiv(ms, dayMs) * dayMs
	k, u := strings.ToLower(jsTrim(fdd.str(unit))), -1
	for i, n := range periods {
		if n == k {
			u = i
			break
		}
	}
	if u < 0 {
		panic(&FddError{"INVALID_UNIT", "Unknown period \"" + fdd.str(unit) + "\" (use hour, day, week, month or year)"})
	}
	var from, length int64
	switch u / 2 {
	case 0:
		from, length = ms-p[8]%3600000, 3600000
	case 1:
		from, length = day, dayMs
	case 2:
		from, length = day-(p[7]+6)%7*dayMs, 7*dayMs
	case 3:
		from, length = daysFromCivil(p[0], p[1], 1)*dayMs, daysIn(p[0], p[1])*dayMs
	default:
		from, length = daysFromCivil(p[0], 1, 1)*dayMs, (daysFromCivil(p[0]+1, 1, 1)-daysFromCivil(p[0], 1, 1))*dayMs
	}
	if end {
		return isoDate(float64(from + length - 1))
	}
	return isoDate(float64(from))
}

// startOf is the first moment of the period the date is in (UTC).
func (fddRuntime) startOf(date, unit any) string { return periodEdge(date, unit, false) }

// endOf is the last moment (...:59.999) of the period the date is in (UTC).
func (fddRuntime) endOf(date, unit any) string { return periodEdge(date, unit, true) }

// ---------- runtime ----------

// now is the current date-time (ISO, like JavaScript's toISOString).
func (fddRuntime) now() string { return isoDate(float64(time.Now().UnixMilli())) }

func (fddRuntime) uuid() string {
	var b [16]byte
	_, _ = crand.Read(b[:])
	b[6] = b[6]&0x0f | 0x40
	b[8] = b[8]&0x3f | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

// random is an integer between min and max.
func (fddRuntime) random(lo, hi any) float64 {
	a, b := fdd.toNum(lo), fdd.toNum(hi)
	return math.Floor(a + float64(mrand.Float64()*(b-a+1)))
}

func (fddRuntime) log(message any) any {
	if s, ok := message.(string); ok {
		fmt.Println(s)
	} else {
		fmt.Println(fdd.json(message))
	}
	return nil
}

func (fddRuntime) sleep(ms any) any {
	time.Sleep(time.Duration(math.Max(0, fdd.toNum(ms))) * time.Millisecond)
	return nil
}

// parallel runs branches concurrently and waits for all; the first branch's panic is raised again.
func (fddRuntime) parallel(branches ...func()) {
	failed := make([]any, len(branches))
	var wg sync.WaitGroup
	for i, b := range branches {
		wg.Add(1)
		go func(i int, b func()) {
			defer wg.Done()
			defer func() { failed[i] = recover() }()
			b()
		}(i, b)
	}
	wg.Wait()
	for _, r := range failed {
		if r != nil {
			panic(r)
		}
	}
}

