package main

func job0SignIn(request any, deps any) (_ any, err error) {
	defer fdd.recoverInto(&err)
	fddFrame := fddVerify.frame("bp-auth-login")
	fddFrame.enter("NODE-AUTH-LOGIN-001")
	var email any = fdd.get(fdd.get(request, "body"), "email")
	var emailCheck any = fdd.checkEmail(email, "email")
	var password any = fdd.get(fdd.get(request, "body"), "password")
	fddFrame.enter("NODE-AUTH-LOGIN-006")
	if !(fdd.truthy(fdd.get(emailCheck, "valid")) && !fdd.isEmpty(password)) {
		fddFrame.enter("NODE-AUTH-LOGIN-009")
		return fdd.obj(
			"status", 401.0,
			"body", fdd.obj(
				"error", fdd.ifElse(fdd.truthy(fdd.get(emailCheck, "valid")), func() any {
					return fdd.get(fdd.checkRequired(password, "password"), "message")
				}, func() any {
					return fdd.get(emailCheck, "message")
				}),
			),
		), nil
	}
	fddFrame.enter("NODE-AUTH-LOGIN-010")
	var lookUpUser any = fddVerify.dep(
		"userService",
		"getUsersByEmail",
		"NODE-AUTH-LOGIN-010",
		fdd.obj("query", fdd.omitNulls(fdd.obj("email", email))),
	)
	status1 := fdd.get(lookUpUser, "status")
	if fdd.eq(status1, 200.0) {
		fddFrame.enter("NODE-AUTH-LOGIN-014")
		if !fdd.eq(fdd.get(fdd.get(lookUpUser, "body"), "passwordHash"), fdd.format("hash:{password}", fdd.obj("password", password))) {
			fddFrame.enter("NODE-AUTH-LOGIN-021")
			return fdd.obj("status", 401.0, "body", fdd.obj("error", "Invalid credentials")), nil
		}
		var id any = fdd.get(fdd.get(lookUpUser, "body"), "id")
		fddFrame.enter("NODE-AUTH-LOGIN-018")
		fddVerify.dep("eventBus", "publishUserLoggedIn", "NODE-AUTH-LOGIN-018", fdd.obj("userId", id))
		fddFrame.enter("NODE-AUTH-LOGIN-019")
		return fdd.obj(
			"status", 200.0,
			"body", fdd.obj(
				"accessToken", fdd.format("TEST-TOKEN-{id}", fdd.obj("id", id)),
				"refreshToken", "REFRESH-TOKEN",
				"expiresIn", 3600.0,
				"tokenType", "Bearer",
			),
		), nil
	} else if fdd.eq(status1, 404.0) {
		fddFrame.enter("NODE-AUTH-LOGIN-022")
		return fdd.obj("status", 401.0, "body", fdd.obj("error", "Invalid credentials")), nil
	} else {
		fddFrame.enter("NODE-AUTH-LOGIN-023")
		panic(NewFddError("UPSTREAM_ERROR", "User Service failed"))
	}
}
